    #[test]
    fn a_plugin_that_claims_to_be_implemented_is() {
        let implemented: &[(&str, &dyn crate::compiler::Compiler)] =
            &[("plugin.java", &crate::compilers::java::COMPILER)];

        for plugin in Registry::builtin().all() {
            let contract = plugin.contract();
            let real = implemented.iter().find(|(id, _)| *id == contract.id);
            match real {
                Some((_, compiler)) => {
                    assert!(
                        contract.produces_artifacts,
                        "{} is written and must say so",
                        contract.id
                    );
                    let wrong = crate::compiler::check_contract(*compiler);
                    assert!(wrong.is_empty(), "{}: {wrong:?}", contract.id);
                }
                None => {
                    assert!(
                        !contract.produces_artifacts,
                        "{} must not be allowed to publish artifacts",
                        contract.id
                    );
                }
            }
        }
    }

    #[test]
    fn every_plugin_refuses_to_execute_and_says_why() {
        let mut policy = Policy::new("test");
        for plugin in Registry::builtin().all() {
            let mut sink = Sink::new();
            let mut ctx = crate::plugin::Context {
                policy: &mut policy,
                diagnostics: &mut sink,
            };

            let error = plugin
                .execute(&mut ctx)
                .expect_err("nothing compiles through the plugin surface");
            assert!(
                error.code == "E0001"
                    || error.code.starts_with("EJ")
                    || error.code.starts_with("EK"),
                "{}: {}",
                plugin.contract().id,
                error.code
            );
            assert_eq!(error.severity, Severity::Error);
            assert_eq!(error.origin, plugin.contract().id);
            assert!(error.suggestion.is_some());
        }
    }

