    #[test]
    fn a_layout_and_a_menu_become_what_aapt2_makes_of_them() {
        let _turn = crate::progress::one_at_a_time();
        let directory = temp_directory("builder-layout");
        let res = directory.join("Res");
        for folder in ["layout", "menu", "values", "drawable", "mipmap-anydpi-v26"] {
            std::fs::create_dir_all(res.join(folder)).unwrap();
        }

        for (path, text) in [
            ("layout/screen.xml", A_LAYOUT),
            ("menu/main.xml", A_MENU),
            ("drawable/mark.xml", A_VECTOR),
            ("mipmap-anydpi-v26/ic_shape.xml", AN_ADAPTIVE_ICON),
            ("values/strings.xml", THE_WORDS),
            ("values/colors.xml", THE_COLOURS),
            ("values/dimens.xml", THE_SIZES),
        ] {
            std::fs::write(res.join(path), text.trim_start()).unwrap();
        }
        std::fs::write(
            directory.join("AndroidManifest.xml"),
            A_MANIFEST.trim_start(),
        )
        .unwrap();
        let root = directory.to_str().unwrap().to_string();

        let mut project = crate::builder::from_manifest(A_MANIFEST).expect("the manifest reads");
        project.values = crate::scaffold::values_files(&root);
        project.resources = crate::scaffold::resource_files(&root);
        assert_eq!(project.values.len(), 3, "three values files");
        assert_eq!(
            project.resources.len(),
            4,
            "a layout, a menu, a vector and an adaptive icon"
        );

        let mut sink = crate::diag::Sink::new();
        let icons = crate::builder::compile_resources_for_test(&project, &mut sink)
            .expect("the resources compile")
            .expect("and there are some");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let named: Vec<&str> = icons
            .compiled
            .assignments()
            .iter()
            .filter(|(kind, _, _)| *kind == crate::resources::Kind::Id)
            .map(|(_, name, _)| name.as_str())
            .collect();
        for one in ["clear", "entry", "list", "save", "title"] {
            assert!(named.contains(&one), "R.id.{one} is missing from {named:?}");
        }
        for (kind, name) in [
            (crate::resources::Kind::Layout, "screen"),
            (crate::resources::Kind::Menu, "main"),
            (crate::resources::Kind::Color, "back"),
            (crate::resources::Kind::Dimension, "big"),
            (crate::resources::Kind::String, "app_name"),
        ] {
            assert!(
                icons.compiled.id(kind, name).is_some(),
                "R.{kind}.{name} is missing"
            );
        }

        for entry in [
            "res/layout/screen.xml",
            "res/menu/main.xml",
            "res/drawable/mark.xml",
            "res/mipmap-anydpi-v26/ic_shape.xml",
        ] {
            let (_, bytes) = icons
                .files
                .iter()
                .find(|(held, _)| held == entry)
                .unwrap_or_else(|| panic!("{entry} is missing"));
            assert_eq!(&bytes[..2], &[0x03, 0x00], "{entry} is not binary XML");
        }

        let key = crate::rsa::generate(2048).expect("a key");
        let mut made = crate::diag::Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_700_000_000, &mut made)
            .expect("the package is written");
        assert!(!made.has_blocking(), "{:?}", made.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("layout conformance: aapt2 is not available here");
            return;
        };
        let ours = directory.join("ours.apk");
        std::fs::write(&ours, &outcome.package).unwrap();

        let compiled = directory.join("compiled.zip");
        let made = std::process::Command::new(&aapt2)
            .args(["compile", "--dir"])
            .arg(res.to_str().unwrap())
            .arg("-o")
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            made.status.success(),
            "aapt2 could not compile the folder: {}",
            String::from_utf8_lossy(&made.stderr)
        );
        let Some(platform) = crate::builder::platform_jar() else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("layout conformance: no android.jar to link against");
            return;
        };
        let theirs = directory.join("theirs.apk");
        let linked = std::process::Command::new(&aapt2)
            .arg("link")
            .arg("-o")
            .arg(theirs.to_str().unwrap())
            .arg("-I")
            .arg(&platform)
            .arg("--manifest")
            .arg(directory.join("AndroidManifest.xml").to_str().unwrap())
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 could not link the folder: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dump = |apk: &std::path::Path, file: &str| -> Vec<String> {
            let out = std::process::Command::new(&aapt2)
                .args(["dump", "xmltree"])
                .arg(apk.to_str().unwrap())
                .args(["--file", file])
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "aapt2 refused {file} in {}: {}",
                apk.display(),
                String::from_utf8_lossy(&out.stderr)
            );
            String::from_utf8_lossy(&out.stdout)
                .lines()
                .map(|one| one.trim().to_string())
                .collect()
        };
        for file in [
            "res/layout/screen.xml",
            "res/menu/main.xml",
            "res/drawable/mark.xml",
            "res/mipmap-anydpi-v26/ic_shape.xml",
        ] {
            assert_eq!(
                dump(&ours, file),
                dump(&theirs, file),
                "{file} is not what aapt2 makes of it"
            );
        }
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "layout conformance: a layout, a menu, a vector drawable and an adaptive icon \
             agree with aapt2 attribute for attribute"
        );
    }

    #[test]
    fn a_manifest_that_says_no_floor_and_no_export_is_given_both() {
        let manifest = r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    package="com.my.app">
    <application android:label="Hello" android:allowBackup="false">
        <activity android:name=".Hello">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
        <activity android:name=".Hidden" android:exported="false">
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
            </intent-filter>
        </activity>
        <service android:name=".Quiet" />
    </application>
</manifest>
"#;
        let settings = crate::settings::Settings::default();
        let written = crate::settings::over_manifest(manifest, &settings);
        let floor = written
            .lines()
            .find(|line| line.trim_start().starts_with("<uses-sdk"))
            .unwrap_or_else(|| panic!("no floor was written:\n{written}"));
        for said in [
            format!("android:minSdkVersion=\"{}\"", settings.min_sdk),
            format!("android:targetSdkVersion=\"{}\"", settings.target_sdk),
        ] {
            assert!(floor.contains(&said), "{floor} lacks {said}");
        }
        assert_eq!(written.matches("<uses-sdk").count(), 1);
        assert_eq!(
            crate::settings::over_manifest(&written, &settings),
            written,
            "writing the floor twice changes nothing"
        );

        let project = crate::builder::from_manifest(&written).expect("the manifest reads");
        let mut sink = crate::diag::Sink::new();
        let prepared = crate::builder::prepare(&project, &mut sink).expect("and prepares");
        let application = prepared
            .root
            .children
            .iter()
            .find(|one| one.name == "application")
            .expect("there is an application");
        let exported = |name: &str| {
            application
                .children
                .iter()
                .find(|one| one.attribute("android:name") == Some(name))
                .and_then(|one| one.attribute("android:exported"))
                .map(str::to_string)
        };
        assert_eq!(
            exported(".Hello").as_deref(),
            Some("true"),
            "what answers an intent was exported before API 31 said it must be written"
        );
        assert_eq!(exported(".Hidden").as_deref(), Some("false"));
        assert_eq!(exported(".Quiet"), None);
    }

