    #[test]
    fn every_qualifier_a_folder_can_carry_means_the_same_to_aapt2() {
        let _turn = crate::progress::one_at_a_time();
        const QUALIFIERS: &[&str] = &[
            "",
            "ldltr",
            "ldrtl",
            "small",
            "normal",
            "large",
            "xlarge",
            "long",
            "notlong",
            "round",
            "notround",
            "widecg",
            "nowidecg",
            "highdr",
            "lowdr",
            "port",
            "land",
            "car",
            "desk",
            "television",
            "appliance",
            "watch",
            "vrheadset",
            "night",
            "notnight",
            "notouch",
            "finger",
            "keysexposed",
            "keyshidden",
            "keyssoft",
            "nokeys",
            "qwerty",
            "12key",
            "navexposed",
            "navhidden",
            "nonav",
            "dpad",
            "trackball",
            "wheel",
            "ldpi",
            "mdpi",
            "hdpi",
            "xhdpi",
            "xxhdpi",
            "xxxhdpi",
            "nodpi",
            "tvdpi",
            "anydpi",
            "sw600dp",
            "w720dp",
            "h1024dp",
            "v26",
            "v31",
            "mcc310",
            "mcc310-mnc004",
            "tr",
            "de",
            "en-rUS",
            "pt-rBR",
            "zh-rCN",
            "b+sr+Latn+RS",
            "b+es+419",
            "fil",
            "sw600dp-land-night-xxhdpi-v31",
            "large-long-notround-port-hdpi",
            "car-night-nokeys-navhidden-v29",
        ];

        let directory = temp_directory("builder-qualifiers");
        let res = directory.join("Res");
        for one in QUALIFIERS {
            let folder = if one.is_empty() {
                "values".to_string()
            } else {
                format!("values-{one}")
            };
            let at = res.join(&folder);
            std::fs::create_dir_all(&at).unwrap();
            std::fs::write(
                at.join("strings.xml"),
                format!(
                    "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n\
                     <resources><string name=\"app_name\">{folder}</string></resources>\n"
                ),
            )
            .unwrap();
        }
        std::fs::write(
            directory.join("AndroidManifest.xml"),
            A_BARE_MANIFEST.trim_start(),
        )
        .unwrap();
        let root = directory.to_str().unwrap().to_string();

        let mut project =
            crate::builder::from_manifest(A_BARE_MANIFEST).expect("the manifest reads");
        project.values = crate::scaffold::values_files(&root);
        project.resources = crate::scaffold::resource_files(&root);
        assert_eq!(
            project.values.len(),
            QUALIFIERS.len(),
            "every folder is read"
        );

        let mut sink = crate::diag::Sink::new();
        crate::builder::compile_resources_for_test(&project, &mut sink)
            .expect("the resources compile");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let key = crate::rsa::generate(2048).expect("a key");
        let mut made = crate::diag::Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_700_000_000, &mut made)
            .expect("the package is written");
        assert!(!made.has_blocking(), "{:?}", made.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("qualifier conformance: aapt2 is not available here");
            return;
        };
        let Some(platform) = crate::builder::platform_jar() else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("qualifier conformance: no android.jar to link against");
            return;
        };
        let ours = directory.join("ours.apk");
        std::fs::write(&ours, &outcome.package).unwrap();

        let compiled = directory.join("compiled.zip");
        let done = std::process::Command::new(&aapt2)
            .args(["compile", "--dir"])
            .arg(res.to_str().unwrap())
            .arg("-o")
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            done.status.success(),
            "aapt2 could not compile the folders: {}",
            String::from_utf8_lossy(&done.stderr)
        );
        let theirs = directory.join("theirs.apk");
        let linked = std::process::Command::new(&aapt2)
            .arg("link")
            .arg("-o")
            .arg(theirs.to_str().unwrap())
            .arg("-I")
            .arg(&platform)
            .arg("--manifest")
            .arg(directory.join("AndroidManifest.xml").to_str().unwrap())
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 could not link the folders: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dump = |apk: &std::path::Path| -> Vec<String> {
            let out = std::process::Command::new(&aapt2)
                .args(["dump", "resources"])
                .arg(apk.to_str().unwrap())
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "aapt2 refused the table in {}: {}",
                apk.display(),
                String::from_utf8_lossy(&out.stderr)
            );
            let mut lines: Vec<String> = String::from_utf8_lossy(&out.stdout)
                .lines()
                .map(|one| one.trim().to_string())
                .filter(|one| one.starts_with('('))
                .collect();
            lines.sort();
            lines
        };
        let mine = dump(&ours);

        assert_eq!(
            mine.len(),
            QUALIFIERS.len() - 1,
            "one line per folder: {mine:?}"
        );
        assert_eq!(
            mine,
            dump(&theirs),
            "a qualifier does not mean here what it means to aapt2"
        );

        const WRONG: &[&str] = &[
            "values-night-land",
            "values-v31-xxhdpi",
            "values-land-sw600dp",
            "values-navhidden-nokeys",
        ];
        for one in WRONG {
            let alone = directory.join(one);
            std::fs::create_dir_all(alone.join(one)).unwrap();
            std::fs::write(
                alone.join(one).join("strings.xml"),
                "<resources><string name=\"app_name\">x</string></resources>\n",
            )
            .unwrap();
            let refused = std::process::Command::new(&aapt2)
                .args(["compile", "--dir"])
                .arg(alone.to_str().unwrap())
                .arg("-o")
                .arg(directory.join("refused.zip").to_str().unwrap())
                .output()
                .unwrap();
            assert!(
                !refused.status.success(),
                "aapt2 took {one}, so refusing it here would be this build's own rule"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "qualifier conformance: {} folders agree with aapt2, and {} orders are \
             refused by both",
            QUALIFIERS.len(),
            WRONG.len()
        );
    }

    #[test]
    fn styles_arrays_and_plurals_are_the_table_aapt2_writes() {
        let _turn = crate::progress::one_at_a_time();
        let directory = temp_directory("builder-bags");
        let res = directory.join("Res");
        std::fs::create_dir_all(res.join("values")).unwrap();
        std::fs::write(res.join("values/things.xml"), THE_BAGS.trim_start()).unwrap();
        std::fs::write(
            directory.join("AndroidManifest.xml"),
            A_BARE_MANIFEST.trim_start(),
        )
        .unwrap();
        let root = directory.to_str().unwrap().to_string();

        let mut project =
            crate::builder::from_manifest(A_BARE_MANIFEST).expect("the manifest reads");
        project.values = crate::scaffold::values_files(&root);
        project.resources = crate::scaffold::resource_files(&root);

        let mut sink = crate::diag::Sink::new();
        crate::builder::compile_resources_for_test(&project, &mut sink)
            .expect("the resources compile");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let key = crate::rsa::generate(2048).expect("a key");
        let mut made = crate::diag::Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_700_000_000, &mut made)
            .expect("the package is written");
        assert!(!made.has_blocking(), "{:?}", made.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("bag conformance: aapt2 is not available here");
            return;
        };
        let Some(platform) = crate::builder::platform_jar() else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("bag conformance: no android.jar to link against");
            return;
        };
        let ours = directory.join("ours.apk");
        std::fs::write(&ours, &outcome.package).unwrap();

        let compiled = directory.join("compiled.zip");
        let done = std::process::Command::new(&aapt2)
            .args(["compile", "--dir"])
            .arg(res.to_str().unwrap())
            .arg("-o")
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            done.status.success(),
            "aapt2 could not compile the folder: {}",
            String::from_utf8_lossy(&done.stderr)
        );
        let theirs = directory.join("theirs.apk");
        let linked = std::process::Command::new(&aapt2)
            .arg("link")
            .arg("-o")
            .arg(theirs.to_str().unwrap())
            .arg("-I")
            .arg(&platform)
            .arg("--manifest")
            .arg(directory.join("AndroidManifest.xml").to_str().unwrap())
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 could not link the folder: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dump = |apk: &std::path::Path| -> Vec<String> {
            let out = std::process::Command::new(&aapt2)
                .args(["dump", "resources"])
                .arg(apk.to_str().unwrap())
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "aapt2 refused the table in {}: {}",
                apk.display(),
                String::from_utf8_lossy(&out.stderr)
            );
            String::from_utf8_lossy(&out.stdout)
                .lines()
                .map(|one| one.trim().to_string())
                .filter(|one| !one.is_empty())
                .collect()
        };
        let mine = dump(&ours);

        for held in [
            "resource 0x7f010000 array/counts",
            "resource 0x7f060000 plurals/apples",
            "resource 0x7f080000 style/Plain",
            "resource 0x7f040000 fraction/half",
            "resource 0x7f050000 id/save",
            "() 0.500000%",
            "() 0.333000%p",
            "() 8.000000dp",
            "(style) size=5 parent=0x01030237",
            "(style) size=1 parent=style/Theme (0x7f080001)",
            "(array) size=5",
            "(plurals) size=3",
            "0x01010031=?0x01010435",
            "0x010100af=0x00000031",
        ] {
            assert!(
                mine.iter().any(|one| one == held || one.ends_with(held)),
                "{held} is missing from the table: {mine:?}"
            );
        }
        assert_eq!(
            mine,
            dump(&theirs),
            "the table is not what aapt2 makes of the same file"
        );

        let mut ready = crate::diag::Sink::new();
        let prepared = crate::builder::prepare(&project, &mut ready).expect("the project prepares");
        let held = prepared.icons.as_ref().expect("there are resources");
        let mut carried = crate::archive::Builder::new();
        carried
            .add(
                "AndroidManifest.xml",
                crate::bundle::encode_manifest(&prepared.root).expect("the manifest is written"),
            )
            .unwrap();
        carried
            .add(
                "resources.pb",
                crate::bundle::encode_resources(&prepared.package, &held.compiled)
                    .expect("the table is written"),
            )
            .unwrap();
        for (name, bytes) in &held.files {
            carried.add(name.clone(), bytes.clone()).unwrap();
        }
        let as_proto = directory.join("proto.apk");
        std::fs::write(&as_proto, carried.finish().unwrap()).unwrap();
        let back = directory.join("back.apk");
        let converted = std::process::Command::new(&aapt2)
            .arg("convert")
            .arg("-o")
            .arg(back.to_str().unwrap())
            .args(["--output-format", "binary"])
            .arg(as_proto.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            converted.status.success(),
            "aapt2 could not read the table a bundle carries: {}",
            String::from_utf8_lossy(&converted.stderr)
        );
        assert_eq!(
            dump(&back),
            mine,
            "the table a bundle carries is not the table a package carries"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("bag conformance: styles, arrays and plurals agree with aapt2 value for value");
    }

    #[test]
    fn attributes_and_styleables_are_what_aapt2_makes_of_them() {
        let _turn = crate::progress::one_at_a_time();
        let directory = temp_directory("builder-attrs");
        let res = directory.join("Res");
        std::fs::create_dir_all(res.join("values")).unwrap();
        std::fs::create_dir_all(res.join("layout")).unwrap();
        std::fs::write(res.join("values/attrs.xml"), THE_ATTRIBUTES.trim_start()).unwrap();
        std::fs::write(res.join("layout/view.xml"), A_CUSTOM_LAYOUT.trim_start()).unwrap();
        std::fs::write(
            directory.join("AndroidManifest.xml"),
            A_BARE_MANIFEST.trim_start(),
        )
        .unwrap();
        let root = directory.to_str().unwrap().to_string();

        let mut project =
            crate::builder::from_manifest(A_BARE_MANIFEST).expect("the manifest reads");
        project.values = crate::scaffold::values_files(&root);
        project.resources = crate::scaffold::resource_files(&root);

        let mut sink = crate::diag::Sink::new();
        let icons = crate::builder::compile_resources_for_test(&project, &mut sink)
            .expect("the resources compile");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        let icons = icons.expect("there are resources");

        let generated = crate::builder::r_source("com.my.app", &icons.compiled);
        for held in [
            "public static final class styleable {",
            "public static final int[] Empty = {  };",
            "public static final int MyView_android_textColor = 0;",
        ] {
            assert!(
                generated.contains(held),
                "R.java is missing {held:?}:\n{generated}"
            );
        }

        let key = crate::rsa::generate(2048).expect("a key");
        let mut made = crate::diag::Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_700_000_000, &mut made)
            .expect("the package is written");
        assert!(!made.has_blocking(), "{:?}", made.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("attribute conformance: aapt2 is not available here");
            return;
        };
        let Some(platform) = crate::builder::platform_jar() else {
            std::fs::remove_dir_all(&directory).ok();
            eprintln!("attribute conformance: no android.jar to link against");
            return;
        };
        let ours = directory.join("ours.apk");
        std::fs::write(&ours, &outcome.package).unwrap();

        let compiled = directory.join("compiled.zip");
        let done = std::process::Command::new(&aapt2)
            .args(["compile", "--dir"])
            .arg(res.to_str().unwrap())
            .arg("-o")
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            done.status.success(),
            "aapt2 could not compile the folder: {}",
            String::from_utf8_lossy(&done.stderr)
        );
        let theirs = directory.join("theirs.apk");
        let java = directory.join("Java");
        std::fs::create_dir_all(&java).unwrap();
        let linked = std::process::Command::new(&aapt2)
            .arg("link")
            .arg("-o")
            .arg(theirs.to_str().unwrap())
            .arg("-I")
            .arg(&platform)
            .arg("--manifest")
            .arg(directory.join("AndroidManifest.xml").to_str().unwrap())
            .arg("--java")
            .arg(java.to_str().unwrap())
            .arg(compiled.to_str().unwrap())
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 could not link the folder: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dump = |apk: &std::path::Path, what: &[&str]| -> Vec<String> {
            let out = std::process::Command::new(&aapt2)
                .arg("dump")
                .args(what)
                .arg(apk.to_str().unwrap())
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "aapt2 refused {}: {}",
                apk.display(),
                String::from_utf8_lossy(&out.stderr)
            );
            String::from_utf8_lossy(&out.stdout)
                .lines()
                .map(|one| one.trim().to_string())
                .filter(|one| !one.is_empty())
                .collect()
        };

        let mine = dump(&ours, &["resources"]);

        for held in [
            "resource 0x7f010005 attr/withEnum",
            "(attr) type=enum size=3",
            "(attr) type=flags size=3",
            "(attr) type=any",
            "(attr) type=integer|enum size=1",
            "(attr) type=reference|color|dimension",
            "second(0x7f030006)=0x00000001",
            "negative(0x7f030003)=0xffffffff",
            "resource 0x7f030002 id/left",
            "withEnum(0x7f010005)=1",
            "0x01010098=?0x01010435",
            "0x01010031=?attr/manyFormats",
        ] {
            assert!(
                mine.iter().any(|one| one == held || one.ends_with(held)),
                "{held} is missing from the table: {mine:?}"
            );
        }
        assert_eq!(
            mine,
            dump(&theirs, &["resources"]),
            "the table is not what aapt2 makes of the same file"
        );

        let layout = ["xmltree", "--file", "res/layout/view.xml"];
        let seen = dump(&ours, &layout);
        for held in [
            "N: app=http://schemas.android.com/apk/res-auto (line=2)",
            "A: http://schemas.android.com/apk/res-auto:withEnum(0x7f010005)=1",
            "A: http://schemas.android.com/apk/res-auto:withFlags(0x7f010006)=0x00000003",
            "A: http://schemas.android.com/apk/res/android:background(0x010100d4)=?0x7f010002",
            "A: http://schemas.android.com/apk/res/android:textColor(0x01010098)=?0x01010435",
        ] {
            assert!(
                seen.iter().any(|one| one == held),
                "{held} is missing from the layout: {seen:?}"
            );
        }
        assert_eq!(
            seen,
            dump(&theirs, &layout),
            "the layout is not what aapt2 makes of the same file"
        );

        let written = std::fs::read_to_string(java.join("com/my/app/R.java"))
            .expect("aapt2 writes an R of its own");
        for name in ["MyView", "Empty"] {
            let theirs = styleable_array(&written, name);
            let ours = styleable_array(&generated, name);
            assert_eq!(
                ours, theirs,
                "R.styleable.{name} is not the array aapt2 writes"
            );
        }
        assert_eq!(styleable_array(&written, "MyView").len(), 4);

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "attribute conformance: attributes, styleables and a layout that reads \
             them agree with aapt2"
        );
    }

    fn styleable_array(source: &str, name: &str) -> Vec<i64> {
        let at = source
            .find(&format!("int[] {name}="))
            .or_else(|| source.find(&format!("int[] {name} =")))
            .unwrap_or_else(|| panic!("no styleable called {name} in\n{source}"));
        let open = source[at..].find('{').expect("an array opens") + at;
        let close = source[open..].find('}').expect("an array closes") + open;
        source[open + 1..close]
            .split(',')
            .map(str::trim)
            .filter(|one| !one.is_empty())
            .map(|one| {
                let one = one.trim_end_matches('L');
                match one.strip_prefix("0x") {
                    Some(hex) => i64::from(u32::from_str_radix(hex, 16).expect("a number") as i32),
                    None => one.parse::<i64>().expect("a number"),
                }
            })
            .collect()
    }

    const THE_ATTRIBUTES: &str = r####"
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <attr name="plainRef" format="reference" />
    <attr name="manyFormats" format="reference|color|dimension" />
    <attr name="noFormat" />
    <attr name="withEnum" format="enum">
        <enum name="first" value="0" />
        <enum name="second" value="1" />
        <enum name="negative" value="-1" />
    </attr>
    <attr name="withFlags" format="flags">
        <flag name="none" value="0" />
        <flag name="left" value="0x01" />
        <flag name="right" value="0x02" />
    </attr>
    <attr name="intAndEnum" format="integer|enum">
        <enum name="auto" value="0" />
    </attr>
    <declare-styleable name="MyView">
        <attr name="plainRef" />
        <attr name="localOnly" format="string" />
        <attr name="android:textColor" />
        <attr name="withEnum" />
    </declare-styleable>
    <declare-styleable name="Empty" />
    <color name="ink">#ff102030</color>
    <string name="app_name">Apk Builder</string>
    <style name="Custom">
        <item name="withEnum">second</item>
        <item name="localOnly">hi</item>
        <item name="android:textSize">16sp</item>
        <item name="android:colorBackground">?attr/manyFormats</item>
        <item name="android:textColor">?android:attr/colorAccent</item>
    </style>
</resources>
"####;

    const A_CUSTOM_LAYOUT: &str = r####"
<?xml version="1.0" encoding="utf-8"?>
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:background="?attr/manyFormats"
    android:textColor="?android:attr/colorAccent"
    app:withEnum="second"
    app:withFlags="left|right"
    app:localOnly="hello"
    app:plainRef="@color/ink" />
"####;

    #[test]
    fn a_refusal_is_written_in_the_language_the_reader_asked_for() {
        let _turn = crate::progress::one_at_a_time();
        let refusal = Diagnostic::new(
            "EY013",
            Severity::Error,
            FailureClass::UserError,
            "core.keystore",
            "The validity period is outside what a certificate may carry.",
        )
        .with_context("Chosen: 20000 days")
        .with_context("Allowed: 30 to 9125 days")
        .with_suggestion("Google Play requires a key valid until at least 22 October 2033.");

        assert_eq!(crate::speech::choose("en"), "en");
        let mut w = crate::json::Writer::new();
        refusal.write_json(&mut w);
        let english = w.finish();
        assert!(
            english.contains("The validity period is outside"),
            "{english}"
        );
        assert!(english.contains("Chosen: 20000 days"), "{english}");

        assert_eq!(crate::speech::choose("tr-TR"), "tr");
        let mut w = crate::json::Writer::new();
        refusal.write_json(&mut w);
        let turkish = w.finish();
        crate::speech::choose("en");

        assert!(
            turkish.contains("Geçerlilik süresi, bir sertifikanın taşıyabileceğinin dışında."),
            "{turkish}"
        );
        assert!(turkish.contains("Seçilen: 20000 days"), "{turkish}");
        assert!(
            turkish.contains("İzin verilen: 30 to 9125 days"),
            "{turkish}"
        );
        assert!(
            turkish.contains("Google Play, en az 22 Ekim 2033"),
            "{turkish}"
        );
        assert!(
            turkish.contains("The validity period is outside what a certificate may carry."),
            "the English is kept beside it: {turkish}"
        );
        assert_eq!(crate::speech::chosen(), "en");
    }

    #[test]
    fn a_java_error_reaches_the_app_in_the_chosen_language() {
        let _turn = crate::progress::one_at_a_time();
        let source =
            "package com.my.app;\nfinal class Broken {\n    String said = \"never closed;\n}\n";
        let refusal =
            crate::compilers::java::compile(source, &crate::compilers::java::Classpath::new())
                .expect_err("an unclosed string is refused");
        assert_eq!(refusal.code, "EJ005");

        crate::speech::choose("tr");
        let mut w = crate::json::Writer::new();
        w.begin_object(None);
        refusal.write_body(&mut w, "built", false);
        w.end_object();
        let body = w.finish();
        let shown = refusal.localized_message();
        crate::speech::choose("en");

        assert_ne!(shown, refusal.message, "the Java error stayed in English");
        assert!(
            body.contains("Bir dizgi ya da metin bloğu açıldı ve hiç kapatılmadı."),
            "the Java error the app reads is translated: {body}"
        );
        assert!(
            body.contains(&refusal.message),
            "the compiler's own English is kept beside it: {body}"
        );
        assert_eq!(refusal.localized_message(), refusal.message);
    }

