    #[test]
    fn a_class_nothing_reaches_does_not_enter_the_package() {
        const MAIN: &str = r#"
package com.tr.yt.lean;

import android.app.Activity;
import android.os.Bundle;

public final class App extends Activity {

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        Used one = new Used();
        one.count();
    }
}
"#;
        const USED: &str = r#"
package com.tr.yt.lean;

final class Used {

    int count() {
        return 1;
    }
}
"#;
        const NEVER: &str = r#"
package com.tr.yt.lean;

final class NeverCalled {

    int count() {
        return 2;
    }
}
"#;

        let directory = temp_directory("builder-lean");
        let root = directory.join("Lean");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt.lean".to_string(),
                label: "Lean".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let sources = root.join("Java");
        std::fs::create_dir_all(&sources).unwrap();
        for (name, text) in [
            ("App.java", MAIN),
            ("Used.java", USED),
            ("NeverCalled.java", NEVER),
        ] {
            std::fs::write(sources.join(name), text.trim_start()).unwrap();
        }

        let project = crate::builder::from_project(&folder).expect("it compiles");
        let named: Vec<&str> = project
            .code
            .iter()
            .map(|one| one.descriptor.as_str())
            .collect();
        assert!(
            named.contains(&"Lcom/tr/yt/lean/NeverCalled;"),
            "it is compiled: {named:?}"
        );

        let package = "com.tr.yt.lean";
        let roots = crate::shrink::roots_from_manifest(&project.manifest, package);
        assert!(
            roots.contains(&"Lcom/tr/yt/lean/App;".to_string()),
            "the activity is a root: {roots:?}"
        );

        let (kept, trimmed) = crate::shrink::apply(project.code.clone(), &roots);
        let left: Vec<&str> = kept.iter().map(|one| one.descriptor.as_str()).collect();
        assert!(
            left.contains(&"Lcom/tr/yt/lean/App;"),
            "the activity stays: {left:?}"
        );
        assert!(
            left.contains(&"Lcom/tr/yt/lean/Used;"),
            "what it reaches stays: {left:?}"
        );
        assert!(
            !left.contains(&"Lcom/tr/yt/lean/NeverCalled;"),
            "what nothing reaches goes: {left:?}"
        );
        assert!(
            trimmed
                .names
                .contains(&"com/tr/yt/lean/NeverCalled".to_string()),
            "and it is named: {:?}",
            trimmed.names
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn members_nothing_reaches_leave_the_classes_that_stay() {
        const MAIN: &str = r#"
package com.tr.yt.deep;

import android.app.Activity;
import android.os.Bundle;

public final class App extends Activity {

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        Model one = new Model();
        one.used = 3;
        setTitle("" + one.twice());
        Runnable later = one;
        later.run();
    }
}
"#;
        const MODEL: &str = r#"
package com.tr.yt.deep;

final class Model implements Runnable {
    int used;
    int neverTouched;

    int twice() {
        return used * 2;
    }

    int neverCalled() {
        return neverTouched + 7;
    }

    public void run() {
    }

    @Override
    public String toString() {
        return "model";
    }
}
"#;
        let directory = temp_directory("builder-deep");
        let root = directory.join("Deep");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt.deep".to_string(),
                label: "Deep".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");
        let sources = root.join("Java");
        std::fs::create_dir_all(&sources).unwrap();
        for (name, text) in [("App.java", MAIN), ("Model.java", MODEL)] {
            std::fs::write(sources.join(name), text.trim_start()).unwrap();
        }
        let project = crate::builder::from_project(&folder).expect("it compiles");
        let roots = vec!["Lcom/tr/yt/deep/App;".to_string()];
        let (kept, trimmed) = crate::shrink::apply_deep(
            project.code.clone(),
            &roots,
            &crate::shrink::Keep::default(),
        );
        let model = kept
            .iter()
            .find(|one| one.descriptor == "Lcom/tr/yt/deep/Model;")
            .expect("the model stays");
        let methods: Vec<&str> = model
            .direct_methods
            .iter()
            .chain(model.virtual_methods.iter())
            .map(|one| one.reference.name.as_str())
            .collect();
        for wanted in ["<init>", "twice", "run", "toString"] {
            assert!(methods.contains(&wanted), "{wanted} stays: {methods:?}");
        }
        assert!(!methods.contains(&"neverCalled"), "{methods:?}");
        let fields: Vec<&str> = model
            .instance_fields
            .iter()
            .map(|one| one.reference.name.as_str())
            .collect();
        assert_eq!(fields, vec!["used"]);
        let app = kept
            .iter()
            .find(|one| one.descriptor == "Lcom/tr/yt/deep/App;")
            .expect("the activity stays");
        assert!(app
            .virtual_methods
            .iter()
            .any(|one| one.reference.name == "onCreate"));
        assert!(trimmed.methods >= 1 && trimmed.fields >= 1, "{trimmed:?}");
        assert_eq!(
            crate::shrink::handlers_in(&[
                "<Button android:onClick=\"sayHello\" /><View android:onClick=\"@{x}\" />"
                    .to_string()
            ]),
            vec!["sayHello".to_string()]
        );
        std::fs::remove_dir_all(&directory).ok();
    }

