    #[test]
    fn the_editor_colours_every_word_the_compiler_reserves() {
        let editor =
            std::fs::read_to_string("Builder/Source/Main/Kotlin/com/apk/builder/Builder.kt")
                .expect("the interface's source must be here");

        let listed = |name: &str| -> Vec<String> {
            let opens = format!("private val {name} = setOf(");
            let at = editor
                .find(&opens)
                .unwrap_or_else(|| panic!("the editor declares no {name} words"))
                + opens.len();
            let mut depth = 1usize;
            let mut end = at;
            for (index, character) in editor[at..].char_indices() {
                match character {
                    '(' => depth += 1,
                    ')' => {
                        depth -= 1;
                        if depth == 0 {
                            end = at + index;
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let body = &editor[at..end];
            let mut words = Vec::new();
            let mut rest = body;
            while let Some(open) = rest.find('"') {
                let after = &rest[open + 1..];
                let Some(close) = after.find('"') else { break };
                words.push(after[..close].to_string());
                rest = &after[close + 1..];
            }
            assert!(!words.is_empty(), "{name} came out empty");
            words
        };

        let java = listed("JAVA");
        let source =
            std::fs::read_to_string("Compilers/Java/Java.rs").expect("the compiler's source");
        let at = source
            .find("const KEYWORDS: &[&str] = &[")
            .expect("the compiler declares its keywords");
        let end = source[at..].find("];").expect("and closes the list") + at;
        let mut reserved: Vec<&str> = Vec::new();
        let mut rest = &source[at..end];
        while let Some(open) = rest.find('"') {
            let after = &rest[open + 1..];
            let Some(close) = after.find('"') else { break };
            reserved.push(&after[..close]);
            rest = &after[close + 1..];
        }
        assert!(reserved.len() >= 50, "{} keywords found", reserved.len());

        let missing: Vec<&&str> = reserved
            .iter()
            .filter(|word| !java.iter().any(|held| held == *word))
            .collect();
        assert!(
            missing.is_empty(),
            "the editor does not colour these Java keywords: {missing:?}"
        );

        for (name, least) in [("KOTLIN", 60), ("RUST", 35), ("CPP", 80)] {
            let held = listed(name);
            assert!(
                held.len() >= least,
                "{name} holds {} words, expected at least {least}",
                held.len()
            );
        }

        for name in [
            "MainActivity.java",
            "MainActivity.kt",
            "Main.cpp",
            "Lib.rs",
            "AndroidManifest.xml",
            "strings.xml",
        ] {
            let suffix = name.rsplit('.').next().unwrap();
            assert!(
                editor.contains(&format!(".{suffix}\"")),
                "the editor knows no grammar for {name}"
            );
        }
    }

    #[test]
    fn no_text_the_interface_shows_carries_a_stray_run_of_spaces() {
        let check = |what: &str, text: &str| {
            assert!(
                !text.contains("  "),
                "{what} carries a run of spaces: {text:?}"
            );
        };

        for subsystem in crate::SUBSYSTEMS {
            check(subsystem.name, subsystem.name);
            check(subsystem.name, subsystem.summary);
        }
        for dependency in crate::BOOTSTRAP_DEPENDENCIES {
            check(dependency, dependency);
        }
        for plugin in crate::plugin::Registry::builtin().all() {
            let contract = plugin.contract();
            check(contract.id, contract.summary);
            for note in contract.non_responsibilities {
                check(contract.id, note);
            }
        }
    }

    fn minimal_dex(version: &[u8; 3]) -> Vec<u8> {
        let mut data = vec![0u8; dex::HEADER_SIZE as usize];
        data[0..4].copy_from_slice(dex::MAGIC);
        data[4..7].copy_from_slice(version);
        data[7] = 0;
        data[32..36].copy_from_slice(&(dex::HEADER_SIZE).to_le_bytes());
        data[36..40].copy_from_slice(&dex::HEADER_SIZE.to_le_bytes());
        data[40..44].copy_from_slice(&dex::ENDIAN_CONSTANT.to_le_bytes());
        seal_dex(&mut data);
        data
    }

    fn seal_dex(data: &mut [u8]) {
        let signature = crate::hash::sha1(&data[32..]);
        data[12..32].copy_from_slice(signature.as_bytes());
        let checksum = crate::binary::checksum::adler32(&data[12..]);
        data[8..12].copy_from_slice(&checksum.to_le_bytes());
    }

    #[test]
    fn an_empty_dex_reads_and_holds_its_own_fields() {
        let data = minimal_dex(b"035");
        let mut sink = Sink::new();
        let file = dex::read(&data, &mut sink).expect("a well-formed DEX must read");

        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());
        assert_eq!(file.header.version, "035");
        assert_eq!(file.header.file_size, dex::HEADER_SIZE);
        assert!(file.classes.is_empty());
        assert!(file.strings.is_empty());

        let integrity = dex::integrity(&data).unwrap();
        assert!(integrity.checksum_matches());
        assert!(integrity.signature_matches());
        assert!(integrity.self_consistent());
    }

    #[test]
    fn a_dex_header_is_checked_before_it_is_believed() {
        type Damage = fn(&mut Vec<u8>);

        let cases: &[(&str, Damage)] = &[
            ("EX004", |d| {
                d[40..44].copy_from_slice(&dex::REVERSE_ENDIAN_CONSTANT.to_le_bytes());
                seal_dex(d);
            }),
            ("EX004", |d| {
                d[40..44].copy_from_slice(&0xdead_beefu32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX005", |d| {
                d[36..40].copy_from_slice(&0x80u32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX006", |d| {
                d[32..36].copy_from_slice(&9_999u32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX007", |d| {
                d[56..60].copy_from_slice(&0xffff_ffffu32.to_le_bytes());
                seal_dex(d);
            }),
        ];

        for (code, damage) in cases {
            let mut data = minimal_dex(b"035");
            damage(&mut data);
            let error = dex::read(&data, &mut Sink::new())
                .expect_err("a header this wrong must be refused");
            assert_eq!(error.code, *code, "message: {}", error.message);
        }
    }

