    #[test]
    fn a_dex_carries_fields_and_methods_dispatched_on_the_object() {
        let bytes = crate::dexwrite::write(&[furnished_activity_class()], &[super_constructor()])
            .expect("a furnished class must be written");

        let mut sink = Sink::new();
        let file = dex::read(&bytes, &mut sink).expect("our own reader must read it");
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());
        assert_eq!(file.class_names(), vec!["com.example.made.MainActivity"]);
        assert!(dex::integrity(&bytes).unwrap().self_consistent());

        let Some((fields, descriptors)) = dexdump(&bytes) else {
            assert!(
                std::env::var("APK_BUILDER_REQUIRE_DEX_CONFORMANCE").is_err(),
                "APK_BUILDER_REQUIRE_DEX_CONFORMANCE is set but dexdump is missing"
            );
            eprintln!("dexwrite conformance: dexdump is not available here");
            return;
        };
        assert_eq!(descriptors, vec!["Lcom/example/made/MainActivity;"]);
        assert_eq!(
            fields.get("field_ids_size").map(|v| v.as_str()),
            Some("3"),
            "three fields were written: {fields:?}"
        );
        eprintln!(
            "dexwrite conformance: {} bytes with 3 fields and a virtual method, read by dexdump",
            bytes.len()
        );
    }

    #[test]
    fn the_dex_this_build_writes_is_read_by_dexdump() {
        let bytes = crate::dexwrite::write(&[sample_activity_class()], &[super_constructor()])
            .expect("the dex must be written");

        let mut sink = Sink::new();
        let file = dex::read(&bytes, &mut sink).expect("our own reader must read it");
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());
        assert_eq!(file.class_names(), vec!["com.example.made.MainActivity"]);
        assert_eq!(
            file.classes[0].superclass.as_deref(),
            Some("android.app.Activity")
        );
        let integrity = dex::integrity(&bytes).unwrap();
        assert!(integrity.self_consistent());

        let Some((fields, descriptors)) = dexdump(&bytes) else {
            assert!(
                std::env::var("APK_BUILDER_REQUIRE_DEX_CONFORMANCE").is_err(),
                "APK_BUILDER_REQUIRE_DEX_CONFORMANCE is set but dexdump is missing"
            );
            eprintln!("dexwrite conformance: dexdump is not available here");
            return;
        };
        assert_eq!(descriptors, vec!["Lcom/example/made/MainActivity;"]);
        assert_eq!(
            fields.get("class_defs_size").map(|v| v.as_str()),
            Some("1"),
            "{fields:?}"
        );
        eprintln!(
            "dexwrite conformance: {} bytes written here and read by dexdump",
            bytes.len()
        );
    }

    #[test]
    fn modified_utf8_survives_a_round_trip_through_both_halves() {
        for text in [
            "",
            "MainActivity",
            "Lcom/example/made/MainActivity;",
            "\u{0}",
            "\u{00e7}\u{011f}\u{00fc}",
            "\u{1f480}",
            "a\u{0}b\u{1f480}c",
        ] {
            let encoded = crate::dexwrite::encode_modified_utf8(text);
            assert_eq!(*encoded.last().unwrap(), 0, "{text:?} must be terminated");
            let back = modified_utf8::decode(&encoded[..encoded.len() - 1]).unwrap();
            assert_eq!(back, text, "{text:?}");
        }
    }

    #[test]
    fn writing_the_same_classes_twice_gives_the_same_bytes() {
        let first =
            crate::dexwrite::write(&[sample_activity_class()], &[super_constructor()]).unwrap();
        let second =
            crate::dexwrite::write(&[sample_activity_class()], &[super_constructor()]).unwrap();
        assert_eq!(first, second);
    }

    #[test]
    fn a_dex_with_no_classes_is_refused() {
        let error = crate::dexwrite::write(&[], &[]).unwrap_err();
        assert_eq!(error.code, "EW010");
    }

    fn call_ffi(f: impl FnOnce() -> *mut std::os::raw::c_char) -> String {
        unsafe {
            let raw = f();
            assert!(!raw.is_null(), "the bridge must always report");
            let text = std::ffi::CStr::from_ptr(raw).to_str().unwrap().to_string();
            crate::ffi::apk_builder_string_free(raw);
            text
        }
    }

    #[test]
    fn the_newest_platform_is_the_one_with_the_highest_number() {
        use crate::builder::api_level_of;
        use std::path::Path;

        let held =
            |name: &str| api_level_of(Path::new("/opt/android-sdk/platforms").join(name).as_path());
        assert_eq!(held("android-9"), Some((9, 0)));
        assert_eq!(held("android-36"), Some((36, 0)));
        assert_eq!(held("android-37.2"), Some((37, 2)));
        assert!(held("android-37.2") > held("android-37"));
        assert!(held("android-37") > held("android-36"));
        assert!(held("android-36") > held("android-9"));

        assert_eq!(held("android-TiramisuPrivacySandbox"), None);
        assert_eq!(held("data"), None);
        assert_eq!(held("android-"), None);

        let Some(jar) = crate::builder::platform_jar() else {
            eprintln!("no android.jar on this machine");
            return;
        };
        let level = api_level_of(jar.parent().unwrap()).expect("a platform folder");
        assert!(
            level.0 >= crate::compiler::NEWEST_DESCRIBED_API,
            "the platform found is {level:?}, older than the one described"
        );
    }

