    #[test]
    fn pbkdf2_matches_the_published_vectors() {
        let cases: &[(&str, &str, u32, usize, &str)] = &[
            (
                "password",
                "salt",
                1,
                32,
                "120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b",
            ),
            (
                "password",
                "salt",
                2,
                32,
                "ae4d0c95af6b46d32d0adff928f06dd02a303f8ef3c251dfd6e2d85a95474c43",
            ),
            (
                "password",
                "salt",
                4096,
                32,
                "c5e478d59288c841aa530db6845c4c8d962893a001ce4e11a4963873aa98134a",
            ),
            (
                "passwordPASSWORDpassword",
                "saltSALTsaltSALTsaltSALTsaltSALTsalt",
                4096,
                40,
                "348c89dbcbd32b2f32d814b8116e84cf2b17347ebc1800181c4e2a1fb8dd53e1c635518c7dac47e9",
            ),
        ];
        for (password, salt, iterations, length, expected) in cases {
            let derived = crate::cipher::pbkdf2_sha256(
                password.as_bytes(),
                salt.as_bytes(),
                *iterations,
                *length,
            )
            .unwrap();
            assert_eq!(
                hex_string(&derived),
                *expected,
                "{password}/{salt}/{iterations}"
            );
        }
    }

    #[test]
    fn a_wrong_password_returns_nothing_rather_than_rubbish() {
        let key = [0x11u8; 32];
        let other = [0x22u8; 32];
        let iv = [0x33u8; 16];
        let secret = b"a private key would be here";
        let sealed = crate::cipher::encrypt_cbc(&key, &iv, secret);

        assert_eq!(
            crate::cipher::decrypt_cbc(&key, &iv, &sealed).unwrap(),
            secret
        );
        let error = crate::cipher::decrypt_cbc(&other, &iv, &sealed).unwrap_err();
        assert_eq!(error.code, "EK002");
    }

    #[test]
    fn the_cipher_round_trips_every_length_across_the_block_boundary() {
        let key = [0x5au8; 32];
        let iv = [0xa5u8; 16];
        for length in 0..80usize {
            let plain: Vec<u8> = (0..length).map(|at| (at * 7 % 251) as u8).collect();
            let sealed = crate::cipher::encrypt_cbc(&key, &iv, &plain);
            assert!(sealed.len() > length, "padding must always be added");
            assert!(sealed.len().is_multiple_of(16));
            assert_eq!(
                crate::cipher::decrypt_cbc(&key, &iv, &sealed).unwrap(),
                plain,
                "length {length}"
            );
        }
    }

    #[test]
    fn a_developer_key_is_sealed_with_their_password_and_openssl_opens_it() {
        let key = crate::rsa::generate(1024).expect("a key must be made");
        let password = "correct horse battery";
        let sealed = crate::rsa::seal_pkcs8(&key, password).expect("the key must seal");

        let reopened = crate::rsa::open_pkcs8(&sealed, password).expect("our own key must open");
        assert_eq!(reopened.modulus(), key.modulus());

        let wrong = crate::rsa::open_pkcs8(&sealed, "not the password").unwrap_err();
        assert_eq!(wrong.code, "EK002");

        let bad = crate::rsa::open_pkcs8(&sealed, "wrong in another way").unwrap_err();
        assert_eq!(bad.code, "EK002");

        let Some(tool) = openssl() else {
            eprintln!("keystore conformance: openssl is not available here");
            return;
        };
        let directory = temp_directory("builder-keystore");
        let path = directory.join("developer.pk8");
        std::fs::write(&path, &sealed).unwrap();

        let opened = std::process::Command::new(&tool)
            .args([
                "pkcs8",
                "-topk8",
                "-inform",
                "DER",
                "-in",
                path.to_str().unwrap(),
                "-passin",
                &format!("pass:{password}"),
                "-nocrypt",
                "-outform",
                "DER",
                "-out",
                directory.join("plain.pk8").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            opened.status.success(),
            "openssl could not open a key this build sealed: {}",
            String::from_utf8_lossy(&opened.stderr)
        );
        let plain = std::fs::read(directory.join("plain.pk8")).unwrap();
        let theirs = crate::rsa::parse_pkcs8(&plain).unwrap();
        assert_eq!(theirs.modulus(), key.modulus());

        let refused = std::process::Command::new(&tool)
            .args([
                "pkcs8",
                "-topk8",
                "-inform",
                "DER",
                "-in",
                path.to_str().unwrap(),
                "-passin",
                "pass:wrong",
                "-nocrypt",
                "-out",
                directory.join("no.pk8").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            !refused.status.success(),
            "a wrong password must not open it"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("keystore conformance: openssl opened a PBES2 key this build sealed, and refused the wrong password");
    }

    #[test]
    fn a_short_password_is_refused_before_a_key_is_written() {
        let key = crate::rsa::generate(1024).unwrap();
        let error = crate::rsa::seal_pkcs8(&key, "short").unwrap_err();
        assert_eq!(error.code, "ER040");
        assert!(error.suggestion.unwrap().contains("only thing between"));
    }

    #[test]
    fn a_name_being_typed_finds_the_types_it_could_be() {
        let directory = temp_directory("builder-symbols");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Java/com/tr/yt/Cabinet.java",
            "package com.tr.yt;\npublic class Cabinet {\n}\nclass CabinetDrawer {\n}\n",
        )
        .unwrap();

        let exact = crate::symbols::matching(&root, "TextView").unwrap();
        assert_eq!(
            exact.first().map(|held| held.qualified.as_str()),
            Some("android.widget.TextView"),
            "got {:?}",
            exact
                .iter()
                .take(4)
                .map(|h| &h.qualified)
                .collect::<Vec<_>>()
        );
        assert_eq!(exact[0].from, crate::symbols::From::Platform);
        assert_eq!(exact[0].package, "android.widget");

        let starting = crate::symbols::matching(&root, "Bitmap").unwrap();
        assert_eq!(
            starting.first().map(|held| held.simple.as_str()),
            Some("Bitmap"),
            "got {:?}",
            starting
                .iter()
                .take(4)
                .map(|h| &h.simple)
                .collect::<Vec<_>>()
        );
        assert!(
            starting
                .iter()
                .any(|held| held.qualified == "android.graphics.BitmapFactory"),
            "a name starting with it must be offered too"
        );

        let initials = crate::symbols::matching(&root, "TV").unwrap();
        assert!(
            initials
                .iter()
                .any(|held| held.qualified == "android.widget.TextView"),
            "TV must reach TextView: {:?}",
            initials
                .iter()
                .take(6)
                .map(|h| &h.simple)
                .collect::<Vec<_>>()
        );

        let mine = crate::symbols::matching(&root, "Cabinet").unwrap();
        let first = mine.first().expect("the project's own type");
        assert_eq!(first.qualified, "com.tr.yt.Cabinet");
        assert_eq!(first.from, crate::symbols::From::Project);
        assert_eq!(first.path, "Java/com/tr/yt/Cabinet.java");
        assert!(
            mine.iter()
                .any(|held| held.qualified == "com.tr.yt.CabinetDrawer"),
            "the second type in a file counts as much as the first"
        );

        let (path, line) =
            crate::symbols::where_written(&root, "com.tr.yt.Cabinet").expect("it is written here");
        assert_eq!(path, "Java/com/tr/yt/Cabinet.java");
        assert_eq!(line, 2);

        assert!(crate::symbols::where_written(&root, "android.widget.TextView").is_none());

        let everything = crate::symbols::matching(&root, "").unwrap();
        assert_eq!(everything.len(), crate::symbols::MOST);

        assert!(crate::symbols::matching(&root, "Qzzxwv")
            .unwrap()
            .is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_type_this_offers_is_one_an_import_of_it_compiles() {
        let directory = temp_directory("builder-symbols-compile");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        for typed in ["ArrayList", "TextView", "Bundle", "Intent"] {
            let offered = crate::symbols::matching(&root, typed).unwrap();
            let best = offered
                .iter()
                .find(|held| held.simple == typed)
                .unwrap_or_else(|| panic!("{typed} was not offered"));

            let source = format!(
                "package com.tr.yt;\nimport {};\npublic class Holds{typed} {{\n    {typed} held;\n}}\n",
                best.qualified
            );
            let produced =
                crate::compilers::java::compile(&source, &crate::compilers::java::Classpath::new());
            assert!(
                produced.is_ok(),
                "importing {} did not compile: {:?}",
                best.qualified,
                produced.err()
            );
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_bridge_offers_names_and_says_where_one_is_written() {
        let directory = temp_directory("builder-symbols-bridge");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Java/com/tr/yt/Ledger.java",
            "package com.tr.yt;\n\npublic class Ledger {\n}\n",
        )
        .unwrap();

        let read = |ptr: *mut std::os::raw::c_char| {
            assert!(!ptr.is_null());
            let held = unsafe { std::ffi::CStr::from_ptr(ptr) }
                .to_string_lossy()
                .into_owned();
            unsafe { crate::ffi::apk_builder_string_free(ptr) };
            held
        };
        let root_c = std::ffi::CString::new(root.clone()).unwrap();

        let needle = std::ffi::CString::new("Ledger").unwrap();
        let answer =
            read(unsafe { crate::ffi::apk_builder_symbols(root_c.as_ptr(), needle.as_ptr()) });
        assert!(is_structurally_valid(&answer), "{answer}");
        assert!(answer.contains("\"found\":true"), "{answer}");
        assert!(
            answer.contains("\"qualified\":\"com.tr.yt.Ledger\""),
            "{answer}"
        );
        assert!(answer.contains("\"from\":\"project\""), "{answer}");
        assert!(answer.contains("Java/com/tr/yt/Ledger.java"), "{answer}");

        let named = std::ffi::CString::new("com.tr.yt.Ledger").unwrap();
        let where_it_is =
            read(unsafe { crate::ffi::apk_builder_where_written(root_c.as_ptr(), named.as_ptr()) });
        assert!(is_structurally_valid(&where_it_is), "{where_it_is}");
        assert!(where_it_is.contains("\"written\":true"), "{where_it_is}");
        assert!(where_it_is.contains("\"line\":3"), "{where_it_is}");

        let platform = std::ffi::CString::new("android.widget.TextView").unwrap();
        let nowhere = read(unsafe {
            crate::ffi::apk_builder_where_written(root_c.as_ptr(), platform.as_ptr())
        });
        assert!(nowhere.contains("\"written\":false"), "{nowhere}");

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_check_refuses_a_manifest_that_names_a_missing_theme_as_the_build_would() {
        let directory = temp_directory("builder-missing-theme");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Themed".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        assert!(crate::builder::check(&root).refusal.is_none());

        let manifest = std::fs::read_to_string(directory.join("AndroidManifest.xml")).unwrap();
        let themed = manifest.replacen(
            "<application",
            "<application android:theme=\"@style/Theme.AppCompat.Light.NoActionBar\"",
            1,
        );
        assert_ne!(themed, manifest, "the manifest has an application to theme");
        std::fs::write(directory.join("AndroidManifest.xml"), themed).unwrap();

        let refusal = crate::builder::check(&root)
            .refusal
            .expect("a theme the project does not hold is refused before a build");
        assert_eq!(refusal.code, "EB042");
        assert!(
            refusal
                .context
                .iter()
                .any(|line| line.contains("Theme.AppCompat.Light.NoActionBar")),
            "{:?}",
            refusal.context
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn source_this_build_cannot_compile_stops_it_rather_than_being_dropped() {
        let directory = temp_directory("builder-uncompiled");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Mixed".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let clear = crate::builder::check(&root);
        assert!(clear.refusal.is_none(), "{:?}", clear.refusal);
        assert!(crate::builder::uncompiled_source(&root).is_empty());

        crate::workspace::write_text(
            &root,
            "Native/screen.cpp",
            "int screen() {
    return 1;
}
",
        )
        .unwrap();

        let found = crate::builder::uncompiled_source(&root);
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].0, "cpp");
        assert_eq!(found[0].1, "Native/screen.cpp");

        let refused = crate::builder::check(&root);
        let refusal = refused.refusal.expect("it must refuse");
        assert_eq!(refusal.code, "EB058");
        assert!(
            refusal
                .context
                .iter()
                .any(|line| line.contains("Native/screen.cpp")),
            "the refusal names the file: {:?}",
            refusal.context
        );
        assert!(
            refusal
                .context
                .iter()
                .any(|line| line.starts_with("Compiled here:") && line.contains("java")),
            "and says what is compiled: {:?}",
            refusal.context
        );

        assert_eq!(
            crate::builder::from_project(&root)
                .expect_err("the build refuses")
                .code,
            "EB058"
        );

        let bin = directory.join("bin").to_str().unwrap().to_string();
        crate::workspace::remove(&root, "Native/screen.cpp", &bin, 1_800_000_000).unwrap();
        assert!(crate::builder::check(&root).refusal.is_none());

        std::fs::remove_dir_all(&directory).ok();
    }

