    #[test]
    fn every_rule_the_policy_applies_is_one_it_lists() {
        let source = std::fs::read_to_string("Builder.rs").expect("this file must be here");
        let at = source
            .find("pub fn inspect_manifest(root: &Element) -> Report {")
            .expect("the inspection is here");
        let end = source[at..]
            .find("\n    pub fn emit(")
            .expect("and it ends")
            + at;
        let body = &source[at..end];

        let mut applied: Vec<String> = Vec::new();
        let mut rest = body;
        while let Some(found) = rest.find("code: \"") {
            let after = &rest[found + 7..];
            let close = after.find('"').expect("a code is quoted");
            applied.push(after[..close].to_string());
            rest = &after[close..];
        }
        applied.sort();
        applied.dedup();

        let listed: Vec<String> = crate::guard::RULES
            .iter()
            .map(|(code, _, _)| (*code).to_string())
            .collect();
        let mut sorted = listed.clone();
        sorted.sort();
        sorted.dedup();

        assert_eq!(
            sorted, applied,
            "the listed rules and the applied rules have drifted apart"
        );
        assert_eq!(
            listed.len(),
            crate::guard::RULES.len(),
            "a rule is listed twice"
        );

        let mut sink = Sink::new();
        let manifest = crate::xml::parse(
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.tr.yt\"><uses-sdk android:minSdkVersion=\"30\"/>\
             <application/></manifest>",
            "AndroidManifest.xml",
            &mut sink,
        )
        .expect("it must parse");
        let report = crate::guard::inspect_manifest(&manifest);
        assert_eq!(
            report.rules_applied,
            crate::guard::RULES.len(),
            "the policy applied {} rules and lists {}",
            report.rules_applied,
            crate::guard::RULES.len()
        );

        for (code, rule, says) in crate::guard::RULES {
            assert!(code.starts_with("EG"), "{code}");
            assert!(rule.contains('-'), "{rule}");
            assert!(says.len() > 30, "{code} says too little: {says}");
            assert!(says.ends_with('.'), "{code} does not finish its sentence");
        }
    }

    #[test]
    fn a_check_says_what_the_policy_would_refuse() {
        let directory = temp_directory("builder-check-policy");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Guarded".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let clear = crate::builder::check(&root);
        let policy = clear.policy.expect("a project that reads has a verdict");
        assert_eq!(policy.verdict(), crate::guard::Verdict::Passed);
        assert_eq!(policy.rules_applied, crate::guard::RULES.len());

        let manifest = crate::workspace::read_text(&root, "AndroidManifest.xml").unwrap();
        let opened = manifest.replace("<application", "<application android:debuggable=\"true\"");
        assert_ne!(opened, manifest, "the manifest must have an application");
        crate::workspace::write_text(&root, "AndroidManifest.xml", &opened).unwrap();

        let refused = crate::builder::check(&root);
        let policy = refused.policy.expect("a verdict");
        assert_eq!(policy.verdict(), crate::guard::Verdict::Refused);
        assert!(crate::guard::fired(&policy, "EG001"));
        assert!(!crate::guard::fired(&policy, "EG002"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_resource_named_like_a_style_becomes_a_field_that_compiles() {
        assert_eq!(
            crate::builder::r_field("Theme.App.Light"),
            "Theme_App_Light"
        );
        assert_eq!(crate::builder::r_field("some-name"), "some_name");
        assert_eq!(crate::builder::r_field("android:one"), "android_one");
        assert_eq!(crate::builder::r_field("plain_name"), "plain_name");
        assert_eq!(crate::builder::r_field("app_name"), "app_name");

        let directory = temp_directory("builder-r-field");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Styled".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Res/values/styles.xml",
            "<resources>\n\
             \x20 <style name=\"Theme.App\">\n\
             \x20   <item name=\"android:textSize\">14sp</item>\n\
             \x20 </style>\n\
             \x20 <style name=\"Theme.App.Light\" parent=\"Theme.App\">\n\
             \x20   <item name=\"android:textColor\">#FF000000</item>\n\
             \x20 </style>\n\
             </resources>\n",
        )
        .unwrap();

        let project = crate::builder::from_project(&root).expect("it must read");
        assert!(project.code.len() > 1, "the R class and the activity");

        let mut sink = Sink::new();
        let table = crate::builder::compile_resources_for_test(&project, &mut sink)
            .unwrap()
            .unwrap();
        let source = crate::builder::r_source("com.tr.yt", &table.compiled);
        assert!(source.contains("Theme_App_Light"), "{source}");
        assert!(!source.contains("Theme.App.Light ="), "{source}");

        assert!(table
            .compiled
            .entries()
            .iter()
            .any(|entry| entry.name == "Theme.App.Light"));

        std::fs::remove_dir_all(&directory).ok();
    }

