        let left = parse_manifest(forwards, "com.f", &mut Sink::new()).unwrap();
        let right = parse_manifest(backwards, "com.f", &mut Sink::new()).unwrap();
        assert_eq!(left, right);
        assert_eq!(left.digest(), right.digest());
