        let long_segment = format!("dir/{}", "b".repeat(crate::vfs::MAX_SEGMENT_BYTES + 1));
        assert_eq!(VirtualPath::parse(&long_segment).unwrap_err().code, "E2008");

        let deep = vec!["d"; crate::vfs::MAX_SEGMENTS + 1].join("/");
