    #[test]
    fn digest_renders_as_lowercase_hex() {
        let digest = crate::hash::sha256(b"abc");
        let hex = digest.to_hex();
        assert_eq!(hex.len(), 64);
        assert!(hex
            .chars()
            .all(|c| c.is_ascii_hexdigit() && !c.is_uppercase()));
        assert_eq!(digest.to_short_hex(4), "ba7816bf");
        assert_eq!(digest.to_short_hex(64).len(), 64);
        assert_eq!(format!("{digest:?}"), format!("sha256:{hex}"));
    }

    #[test]
    fn field_hashing_cannot_be_confused_by_moving_a_boundary() {
        let left = crate::hash::sha256_fields(&[("a", b"ab"), ("b", b"c")]);
        let right = crate::hash::sha256_fields(&[("a", b"a"), ("b", b"bc")]);
        assert_ne!(left, right);

        assert_ne!(
            crate::hash::sha256_fields(&[("a", b"x")]),
            crate::hash::sha256_fields(&[("b", b"x")])
        );

        assert_eq!(
            crate::hash::sha256_fields(&[("a", b"x"), ("b", b"y")]),
            crate::hash::sha256_fields(&[("a", b"x"), ("b", b"y")])
        );
    }

